const commitResult = store.commitPreparedServerOption({
    ...store.serverOption,
    adminPort: 9301
}, {
    markLastKnownGood: false,
    pendingRestartScopes: ["admin-server"]
});

expect(commitResult.success).toBe(true);
expect(store.revisionState.currentRevision).toBe(2);
expect(store.revisionState.lastKnownGoodRevision).toBe(1);
expect(store.revisionState.pendingRestartScopes).toEqual(["admin-server"]);
const committedOption = store.serverOption;

const adminServer = new AdminServer({} as any, false);
const permanentHandler = (adminServer as any)._permanentErrorHandler as Function;
expect(typeof permanentHandler).toBe("function");

const srv: any = (adminServer as any)._server;
// 최초 상태: error listener 1개 (영구 핸들러만).
expect(srv.listeners("error").length).toBe(1);
expect(srv.listeners("error")[0]).toBe(permanentHandler);

// 반복 listen → close.
for(let i = 0; i < 10; i++) {
    const port = await adminServer.listen(0, "127.0.0.1");
    expect(port).toBeGreaterThan(0);
    // listen 직후에도 영구 핸들러는 유지되고, listen 임시 리스너는 제거된 상태 (on 'listening' 콜백에서 removeListener).
    expect(srv.listeners("error").length).toBeLessThanOrEqual(1);
    expect(srv.listeners("error").length).toBeGreaterThanOrEqual(1);
    expect(srv.listeners("error")).toContain(permanentHandler);
    await adminServer.close();
    // close 후에도 영구 핸들러는 살아있어야 한다.
    expect(srv.listeners("error")).toContain(permanentHandler);
}

// 최종 상태 체크.
expect(srv.listeners("error").length).toBe(1);
expect(srv.listeners("error")[0]).toBe(permanentHandler);

await fs.writeFile(Path.join(testRoot.rootDir, "config", ".key"), "should-not-leak", {encoding: "utf-8"});

const traversalResponse = await httpRequest({port, path: "/../config/.key"});
const apiFallbackResponse = await httpRequest({port, path: "/api/does-not-exist"});

expect(traversalResponse.statusCode).toBe(404);
expect(traversalResponse.body).not.toContain("should-not-leak");
expect(apiFallbackResponse.statusCode).toBe(404);
expect(apiFallbackResponse.body).not.toContain("baseline admin index");

expect(statuses[0]).toMatchObject({
    clientId: "client-a",
    name: "Client A",
    protocolVersion: CONTROL_PROTOCOL_V2,
    legacy: false
});

expect(configFile.isFile()).toBe(true);
expect(store.serverOption.key).not.toBe(DEFAULT_KEY);
expect(store.serverOption).toMatchObject({
    adminPort: 9300,
    adminBindHost: "127.0.0.1",
    adminTls: true,
    port: 9126,
    tls: false,
    controlProtocolMode: "mixed",
    allowLegacyControlAuth: false,
    tunnelingOptions: []
});

const read = JSON.parse((await httpRequest({port, path: "/api/serverOption", headers: {cookie}})).body);
const insecureOption = read.serverOption;
insecureOption.adminTls = false;
insecureOption.adminBindHost = "0.0.0.0";

const response = await httpRequest({
    port,
    path: "/api/serverOption",
    method: "POST",
    headers: {
        "Content-Type": "application/json",
        cookie,
        "x-csrf-token": csrfToken
    },
    body: JSON.stringify({...insecureOption, expectedRevision: read.revisionState.currentRevision})
});

expect(response.statusCode).toBe(400);
expect(JSON.parse(response.body)).toMatchObject({
    success: false,
    legacyFlagsRequired: [LEGACY_ADMIN_HTTP_FLAG, LEGACY_ADMIN_REMOTE_FLAG]
